const inputConfig = $input.first()?.json || {};
const config = {
  chatwootBaseUrl: 'http://chatwoot:3000',
  accountId: 2,
  inboxId: 9,
  apiToken: 'Ee8z4N8PX1iD77U7uoMjv7jK',
  timezone: 'America/Guayaquil',
  filterMode: 'created_at',
  requireInboxMatch: true,
  maxPages: Number(inputConfig.maxPages || 200),
  concurrency: Number(inputConfig.concurrency || 8),
  dateMode: inputConfig.dateMode || 'custom',
  customStartDate: inputConfig.customStartDate || '2026-04-22',
  customEndDate: inputConfig.customEndDate || '2026-04-24',
};

let rangeStart;
let rangeEnd;

if (config.dateMode === 'custom') {
  rangeStart = DateTime.fromISO(config.customStartDate, { zone: config.timezone }).startOf('day');
  rangeEnd = DateTime.fromISO(config.customEndDate, { zone: config.timezone }).endOf('day');
} else {
  const yesterday = DateTime.now().setZone(config.timezone).minus({ days: 1 });
  rangeStart = yesterday.startOf('day');
  rangeEnd = yesterday.endOf('day');
}

function pick(...values) {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim() === '') continue;
    return value;
  }
  return null;
}

function asText(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
}

function asIsoDateTime(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') {
    const millis = value > 9999999999 ? value : value * 1000;
    return DateTime.fromMillis(millis, { zone: 'utc' }).toISO();
  }
  if (typeof value === 'string') {
    const numeric = Number(value);
    if (!Number.isNaN(numeric) && value.trim() !== '') {
      const millis = numeric > 9999999999 ? numeric : numeric * 1000;
      return DateTime.fromMillis(millis, { zone: 'utc' }).toISO();
    }
    const parsed = DateTime.fromISO(value, { zone: 'utc' });
    if (parsed.isValid) return parsed.toISO();
  }
  return null;
}

function inRange(value) {
  const iso = asIsoDateTime(value);
  if (!iso) return false;
  const dt = DateTime.fromISO(iso, { zone: 'utc' }).setZone(config.timezone);
  return dt >= rangeStart && dt <= rangeEnd;
}

function localDateFromIso(value) {
  if (!value) return null;
  return DateTime.fromISO(value, { zone: 'utc' }).setZone(config.timezone).toISODate();
}

function normalizeKey(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function parseStructuredText(text) {
  const parsed = {};
  const lines = String(text || '')
    .split(String.fromCharCode(10))
    .map((line) => line.replaceAll(String.fromCharCode(13), ''));
  for (const line of lines) {
    const match = line.match(/^\s*([A-Za-z0-9_ ]+)\s*:\s*(.+?)\s*$/);
    if (!match) continue;
    parsed[normalizeKey(match[1])] = match[2].trim();
  }
  return parsed;
}

function parseFlowMessage(text) {
  const parsed = parseStructuredText(text);
  const required = ['name', 'identifier', 'email', 'city'];
  const complete = required.every((key) => asText(parsed[key]));
  const hasFlowSignal = asText(parsed.flow_token) || complete;
  return {
    found: Boolean(hasFlowSignal),
    complete,
    fields: {
      name: asText(parsed.name),
      identifier: asText(parsed.identifier),
      email: asText(parsed.email),
      city: asText(parsed.city),
      intent: asText(parsed.intent),
      flow_token: asText(parsed.flow_token),
    },
    raw: hasFlowSignal ? String(text || '') : null,
  };
}

function normalizeText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const MODEL_PATTERNS = [
  { key: 'grand_i10_hatchback', label: 'GRAND I10 HATCHBACK', regex: /\bgrand\s*i10\s*(hb|hatchback)\b/i },
  { key: 'grand_i10_sedan', label: 'GRAND I10 SEDAN', regex: /\bgrand\s*i10\s*sedan\b/i },
  { key: 'grand_i10', label: 'GRAND I10', regex: /\bgrand\s*i10\b/i },
  { key: 'accent', label: 'ACCENT', regex: /\baccent\b/i },
  { key: 'creta', label: 'CRETA', regex: /\bcreta\b/i },
  { key: 'tucson', label: 'TUCSON', regex: /\btucson\b/i },
  { key: 'venue', label: 'VENUE', regex: /\bvenue\b/i },
  { key: 'kona', label: 'KONA', regex: /\bkona\b/i },
  { key: 'santa_fe', label: 'SANTA FE', regex: /\bsanta\s*fe\b/i },
];

function detectModelFromText(text) {
  const source = String(text || '');
  for (const pattern of MODEL_PATTERNS) {
    if (pattern.regex.test(source)) {
      return {
        key: pattern.key,
        label: pattern.label,
        source,
      };
    }
  }
  return null;
}

function modelKeyFromValue(value) {
  const normalized = normalizeText(value);
  if (!normalized) return null;
  const matched = MODEL_PATTERNS.find((pattern) => pattern.regex.test(normalized));
  return matched ? matched.key : normalized;
}

function getFirstUserMessage(messages) {
  return messages.find((message) => {
    const senderType = String(message?.sender?.type || message?.sender_type || '').toLowerCase();
    return senderType === 'contact' || Number(message?.message_type) === 0;
  }) || null;
}

function firstPayloadArray(response) {
  if (Array.isArray(response)) return response;
  if (Array.isArray(response?.payload)) return response.payload;
  if (Array.isArray(response?.data?.payload)) return response.data.payload;
  if (Array.isArray(response?.data)) return response.data;
  return [];
}

function firstPayloadObject(response) {
  if (response?.payload && !Array.isArray(response.payload)) return response.payload;
  if (response?.data?.payload && !Array.isArray(response.data.payload)) return response.data.payload;
  if (response?.data && !Array.isArray(response.data)) return response.data;
  return response;
}


async function apiRequest(method, path, options = {}) {
  let lastError = null;
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      return await this.helpers.httpRequest({
        method,
        url: `${config.chatwootBaseUrl}/api/v1/accounts/${config.accountId}${path}`,
        headers: {
          'Api-Access-Token': config.apiToken,
          Accept: 'application/json',
        },
        json: true,
        timeout: 30000,
        ...options,
      });
    } catch (error) {
      lastError = error;
      const statusCode = Number(error?.response?.status || error?.statusCode || 0);
      const retriable = statusCode >= 500 || statusCode === 429 || statusCode === 0;
      if (!retriable || attempt === 3) break;
      await new Promise((resolve) => setTimeout(resolve, attempt * 1000));
    }
  }
  throw lastError;
}



async function fetchConversations() {
  const all = [];
  const previousDate = rangeStart.minus({ days: 1 }).toISODate();
  const nextDate = rangeEnd.plus({ days: 2 }).startOf('day').toISODate();
  const payload = [
    {
      attribute_key: 'inbox_id',
      filter_operator: 'equal_to',
      values: [String(config.inboxId)],
      query_operator: 'AND',
    },
    {
      attribute_key: 'created_at',
      filter_operator: 'is_greater_than',
      values: [previousDate],
      query_operator: 'AND',
    },
    {
      attribute_key: 'created_at',
      filter_operator: 'is_less_than',
      values: [nextDate],
      query_operator: '',
    },
  ];

  for (let page = 1; page <= config.maxPages; page += 1) {
    const response = await apiRequest('POST', '/conversations/filter', {
      qs: { page },
      body: { payload },
    });
    const conversations = firstPayloadArray(response);
    if (!conversations.length) break;
    all.push(...conversations);
  }

  return all;
}


async function fetchMessages(conversationId) {
  const response = await apiRequest('GET', `/conversations/${conversationId}/messages`);
  return firstPayloadArray(response);
}

async function fetchContact(contactId) {
  if (!contactId) return null;
  try {
    const response = await apiRequest('GET', `/contacts/${contactId}`);
    return firstPayloadObject(response);
  } catch (error) {
    return null;
  }
}

function buildStep(customAttributes, completedData, completedStep6) {
  const phase = asText(customAttributes.booking_phase) || asText(customAttributes.booking_intent) || 'sin_dato';
  if (completedStep6) return 'paso6';
  if (completedData) return 'paso4';
  return phase;
}

const conversations = await fetchConversations();
const inScopeConversations = conversations.filter((conversation) => {
  const inboxId = Number(conversation.inbox_id || conversation?.meta?.inbox?.id || 0);
  if (config.requireInboxMatch && inboxId !== config.inboxId) return false;

  const createdInRange = inRange(conversation.created_at);
  return createdInRange;
});

async function processConversation(conversation) {
  const inboxId = Number(conversation.inbox_id || conversation?.meta?.inbox?.id || 0);
  const createdInRange = inRange(conversation.created_at);
  const activeInRange = inRange(conversation.last_activity_at || conversation.timestamp || conversation.updated_at);
  const customAttributes = conversation.custom_attributes || {};
  const additionalAttributes = conversation.additional_attributes || {};
  const sender = conversation?.meta?.sender || {};
  const [contactResult, messagesResult] = await Promise.allSettled([
    fetchContact(sender.id || conversation.contact_id || conversation?.meta?.sender?.id),
    fetchMessages(conversation.id),
  ]);
  const contact = contactResult.status === 'fulfilled' ? contactResult.value : null;
  const messages = messagesResult.status === 'fulfilled' ? messagesResult.value : [];
  const contactPayload = contact?.payload || contact || {};
  const contactAttrs = contactPayload.custom_attributes || {};

  let flowMatch = null;
  for (const message of messages) {
    const parsed = parseFlowMessage(message.content || message.processed_message_content || '');
    if (parsed.found) {
      flowMatch = {
        message_id: message.id,
        created_at: asIsoDateTime(message.created_at || message.updated_at),
        ...parsed,
      };
      if (parsed.complete) break;
    }
  }

  const firstUserMessage = getFirstUserMessage(messages);
  const firstUserMessageText = asText(firstUserMessage?.content || firstUserMessage?.processed_message_content);
  const firstUserMessageModel = detectModelFromText(firstUserMessageText);

  const number = asText(pick(sender.phone_number, contactPayload.phone_number, contactPayload.identifier, customAttributes.phone, customAttributes.customer_phone));
  const name = asText(pick(customAttributes.name, contactPayload.name, sender.name, customAttributes.customer_name, flowMatch?.fields?.name));
  const email = asText(pick(customAttributes.email, contactPayload.email, sender.email, contactAttrs.email, flowMatch?.fields?.email));
  const identifier = asText(pick(customAttributes.identifier, contactPayload.identifier, contactAttrs.identifier, flowMatch?.fields?.identifier));
  const city = asText(pick(customAttributes.selected_city, customAttributes.city, contactAttrs.city, flowMatch?.fields?.city));
  const latestSelectedModel = asText(pick(customAttributes.latest_selected_model, customAttributes.selected_model, firstUserMessageModel?.label));
  const model = asText(pick(customAttributes.selected_model, customAttributes.latest_selected_model, firstUserMessageModel?.label));
  const establishment = asText(pick(customAttributes.selected_establishment_name, customAttributes.establishment_name));
  const appointmentDate = asText(customAttributes.selected_date);
  const appointmentTime = asText(customAttributes.selected_time);
  const advisorName = asText(pick(customAttributes.selected_advisor_name, customAttributes.advisor_name, customAttributes.sales_advisor_name));
  const leadStatus = asText(pick(customAttributes.lead_status, customAttributes.booking_phase, customAttributes.booking_intent));

  const structuredComplete = [name, email, identifier, number, city].every(Boolean);
  const flowComplete = Boolean(flowMatch?.complete);
  const completedData = structuredComplete || flowComplete || customAttributes.booking_personal_data_complete === true;
  const completedStep6 = Boolean(
    customAttributes.active_appointment_id ||
    (appointmentDate && appointmentTime) ||
    customAttributes.booking_phase6_ready === true
  );
  const selectedModelKey = modelKeyFromValue(model);
  const firstMessageModelKey = firstUserMessageModel?.key || null;
  const firstMessageModelMatchesSelected = Boolean(selectedModelKey && firstMessageModelKey && selectedModelKey === firstMessageModelKey);
  const createdAt = asIsoDateTime(conversation.created_at);
  const lastActivityAt = asIsoDateTime(conversation.last_activity_at || conversation.timestamp || conversation.updated_at);
  const reportDate = localDateFromIso(createdAt) || rangeStart.toISODate();
  const labels = Array.isArray(conversation.labels) ? conversation.labels : [];

  return {
    json: {
      conversation_id: conversation.id,
      contact_id: sender.id || contactPayload.id || conversation.contact_id || null,
      account_id: config.accountId,
      inbox_id: inboxId,
      inbox_name: asText(conversation?.meta?.inbox?.name) || asText(conversation?.inbox?.name) || 'WABA Hyundai',
      conversation_status: asText(conversation.status),
      created_at: createdAt,
      last_activity_at: lastActivityAt,
      report_start_at: rangeStart.toUTC().toISO(),
      report_end_at: rangeEnd.toUTC().toISO(),
      report_date: reportDate,
      created_in_range: createdInRange,
      active_in_range: activeInRange,
      report_basis: 'created_at',
      created_yesterday: createdInRange,
      active_yesterday: activeInRange,
      number,
      name,
      email,
      identifier,
      city,
      model,
      latest_selected_model: latestSelectedModel,
      establishment,
      appointment_date: appointmentDate,
      appointment_time: appointmentTime,
      advisor_name: advisorName,
      lead_status: leadStatus,
      assignee_name: asText(conversation?.meta?.assignee?.name),
      team_name: asText(conversation?.meta?.team?.name),
      first_user_message_text: firstUserMessageText,
      first_message_model_detected: firstUserMessageModel?.label || null,
      first_message_model_key: firstMessageModelKey,
      first_message_model_matches_selected: firstMessageModelMatchesSelected,
      step: buildStep(customAttributes, completedData, completedStep6),
      completed_data: completedData,
      completed_data_source: structuredComplete ? 'structured_fields' : (flowComplete ? 'flow_message' : (customAttributes.booking_personal_data_complete === true ? 'conversation_flag' : 'not_completed')),
      completed_step6: completedStep6,
      validation: {
        has_name: Boolean(name),
        has_email: Boolean(email),
        has_identifier: Boolean(identifier),
        has_number: Boolean(number),
        has_city: Boolean(city),
        structured_complete: structuredComplete,
        flow_complete: flowComplete,
      },
      flow_message_match: flowMatch,
      labels,
      custom_attributes: customAttributes,
      additional_attributes: additionalAttributes,
      contact_snapshot: {
        id: sender.id || contactPayload.id || null,
        name: asText(contactPayload.name) || asText(sender.name),
        email: asText(contactPayload.email) || asText(sender.email),
        phone_number: asText(contactPayload.phone_number) || asText(sender.phone_number),
      },
      message_count: messages.length,
      fetch_warnings: {
        contact_failed: contactResult.status === 'rejected',
        messages_failed: messagesResult.status === 'rejected',
      },
      raw_payload: conversation,
    },
  };
}

async function mapWithConcurrency(items, limit, mapper) {
  const results = [];
  for (let index = 0; index < items.length; index += limit) {
    const batch = items.slice(index, index + limit);
    const batchResults = await Promise.all(batch.map(mapper));
    results.push(...batchResults);
  }
  return results;
}

const filtered = await mapWithConcurrency(inScopeConversations, Math.max(1, config.concurrency), processConversation);

filtered.sort((a, b) => {
  const aDate = a.json.last_activity_at || a.json.created_at || '';
  const bDate = b.json.last_activity_at || b.json.created_at || '';
  return aDate < bDate ? 1 : -1;
});

return filtered;

const items = $input.all();
const details = items.map((item) => item.json);
const createdInRange = details.filter((item) => item.created_in_range);
const completedData = createdInRange.filter((item) => item.completed_data);
const completedStep6 = createdInRange.filter((item) => item.completed_step6);
const reportDates = [...new Set(details.map((item) => item.report_date).filter(Boolean))].sort();
const reportStartAt = details[0]?.report_start_at || null;
const reportEndAt = details[0]?.report_end_at || null;

return [{
  json: {
    workflow_name: 'Chatwoot - WABA Hyundai Daily Validation',
    report_date: reportDates.length === 1 ? reportDates[0] : null,
    report_dates: reportDates,
    report_start_at: reportStartAt,
    report_end_at: reportEndAt,
    inbox_id: 9,
    inbox_name: 'WABA Hyundai',
    account_id: 2,
    summary: {
      conversations_with_activity: details.length,
      conversations_created_in_range: createdInRange.length,
      completed_data: completedData.length,
      completed_step6: completedStep6.length,
      stayed_step4: completedData.length - completedStep6.length,
    },
    details,
  },
}];

const payload = $input.first().json;
const summary = payload.summary || {};
const details = payload.details || [];

function esc(value) {
  if (value === undefined || value === null || value === '') return '-';
  return String(value).replace(/\|/g, '\\|').replace(/\n/g, ' ').trim() || '-';
}

const lines = [];
lines.push('# Reporte Chatwoot - ' + payload.inbox_name);
lines.push('');
lines.push('- Rango analizado: `' + esc(payload.report_start_at) + '` a `' + esc(payload.report_end_at) + '`');
lines.push('- Fechas del detalle: `' + esc((payload.report_dates || []).join(', ')) + '`');
lines.push('- Account ID: `' + payload.account_id + '`');
lines.push('- Inbox ID: `' + payload.inbox_id + '`');
lines.push('');
lines.push('## Resumen');
lines.push('');
lines.push('| Indicador | Valor |');
lines.push('| --- | ---: |');
lines.push('| Conversaciones con actividad | ' + (summary.conversations_with_activity || 0) + ' |');
lines.push('| Conversaciones creadas en rango | ' + (summary.conversations_created_in_range || 0) + ' |');
lines.push('| Completaron datos | ' + (summary.completed_data || 0) + ' |');
lines.push('| Llegaron a paso6 | ' + (summary.completed_step6 || 0) + ' |');
lines.push('| Se quedaron en paso4 | ' + (summary.stayed_step4 || 0) + ' |');
lines.push('');
lines.push('## Detalle');
lines.push('');
lines.push('| report_date | numero | nombre | correo | identificacion | ciudad | modelo | establecimiento | paso | completed_data | fuente |');
lines.push('| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |');
for (const item of details) {
  lines.push('| ' + esc(item.report_date) + ' | ' + esc(item.number) + ' | ' + esc(item.name) + ' | ' + esc(item.email) + ' | ' + esc(item.identifier) + ' | ' + esc(item.city) + ' | ' + esc(item.model) + ' | ' + esc(item.establishment) + ' | ' + esc(item.step) + ' | ' + (item.completed_data ? 'true' : 'false') + ' | ' + esc(item.completed_data_source) + ' |');
}

return [{
  json: {
    ...payload,
    markdown: lines.join('\n'),
  },
}];

const payload = $input.first().json;
const details = payload.details || [];

return details.map((item) => ({
  json: {
    report_date: item.report_date || null,
    conversation_id: item.conversation_id || null,
    number: item.number || null,
    name: item.name || null,
    email: item.email || null,
    identifier: item.identifier || null,
    city: item.city || null,
    model: item.model || null,
    first_message_model_detected: item.first_message_model_detected || null,
    first_message_model_matches_selected: item.first_message_model_matches_selected || false,
    establishment: item.establishment || null,
    appointment_date: item.appointment_date || null,
    appointment_time: item.appointment_time || null,
    step: item.step || null,
  },
}));

const payload = $input.first().json;
const details = payload.details || [];

const rows = [{
  metric: 'report_date',
  value: payload.report_date || (Array.isArray(payload.report_dates) ? payload.report_dates.join(', ') : null),
}, {
  metric: 'total_conversations',
  value: details.length,
}, {
  metric: 'completed_data',
  value: details.filter((item) => item.completed_data).length,
}, {
  metric: 'with_model_selected',
  value: details.filter((item) => item.model).length,
}, {
  metric: 'with_model_selected_first_message',
  value: details.filter((item) => item.first_message_model_detected).length,
}, {
  metric: 'with_model_match_first_message',
  value: details.filter((item) => item.first_message_model_matches_selected).length,
}, {
  metric: 'with_establishment_selected',
  value: details.filter((item) => item.establishment).length,
}, {
  metric: 'with_appointment_date',
  value: details.filter((item) => item.custom_attributes?.selected_date).length,
}, {
  metric: 'with_appointment_time',
  value: details.filter((item) => item.custom_attributes?.selected_time).length,
}];

return rows.map((row) => ({ json: row }));
